// Failure ends the contract; loot already collected and EX partial rewards remain.
let questFailureDeathReceipt=null;
function questFailureRecord(reason){const q=campaign().contract;if(!q)return null;return{id:q.id||'boss:'+q.target,name:guildQuest(q.id||'boss:'+q.target)?.name||SPECIES[q.target]?.name||'討伐依頼',reason,progress:q.progress||0,required:q.required||1,at:Date.now()};}
function commitQuestFailure(reason){if(!campaign().contract)return true;const receipt=questFailureRecord(reason);return worldTransaction(()=>{campaign().lastQuestFailure=receipt;campaign().contract=null;});}
const questFailureValidateBase=validateSave;validateSave=data=>{const out=questFailureValidateBase(data),r=data.p.campaign?.lastQuestFailure;if(r&&out.p.campaign){if(typeof r.id!=='string'||r.id.length>100||typeof r.name!=='string'||r.name.length>100||!['defeat','retreat'].includes(r.reason)||!Number.isSafeInteger(r.progress)||r.progress<0||!Number.isSafeInteger(r.required)||r.required<1||!Number.isFinite(r.at))throw Error('依頼結果が不正です');out.p.campaign.lastQuestFailure={id:r.id,name:r.name,reason:r.reason,progress:r.progress,required:r.required,at:r.at};}return out;};
function showQuestFailureOutcome(reason,receipt,saved=true){const defeat=reason==='defeat';worldMenu(defeat?'敗北':'クエスト失敗','<div class="quest-outcome"><span class="quest-outcome-symbol" aria-hidden="true">✕</span><p class="quest-outcome-label">'+(receipt?'クエスト失敗':'DEFEATED')+'</p><h1>'+(defeat?'力尽きました':'クエスト失敗')+'</h1><p class="quest-outcome-reason">'+(defeat?'戦闘に敗北しました。':'目標達成前に帰還しました。')+'</p>'+(receipt?'<h3>'+gearEscape(receipt.name)+'</h3><p>討伐数 '+receipt.progress+' / '+receipt.required+' · 依頼報酬なし</p><p>掲示板で受注し直すと、最初から挑戦できます。</p>':'')+'<p>装備・成長・回収済み素材・ゴールドは失いません。</p><p>地面に残した素材は帰還すると失われます。EXの削り素材は別途精算されます。</p>'+(!saved?'<p role="alert">保存できませんでした。空き容量を確認して、帰還を再試行してください。</p>':'')+'<button data-outcome-primary onclick="'+(defeat?'returnVillage()':'showVillage()')+'">'+(defeat?'村へ帰還する':'依頼掲示板へ')+'</button></div>','questOutcome');const card=$('card');card.setAttribute('data-quest-outcome',reason);card.querySelector('h2')?.setAttribute('data-world-death','');card.querySelector('h2')?.setAttribute('data-defeat-menu','');card.querySelector('.close')?.remove();menuFocusElement(card.querySelector('[data-outcome-primary]'));}
showDefeatMenu=()=>{let receipt=questFailureRecord('defeat');if(receipt)questFailureDeathReceipt={owner:p,receipt};else receipt=questFailureDeathReceipt?.owner===p?questFailureDeathReceipt.receipt:null;const saved=commitQuestFailure('defeat');showQuestFailureOutcome('defeat',receipt?.reason==='defeat'?receipt:null,saved);};
const questFailureReturnBase=returnVillage;returnVillage=()=>{if(villageOpen)return questFailureReturnBase();const reason=dead?'defeat':'retreat',fail=!!campaign().contract&&(dead||!campaign().contract.killed),receipt=fail?questFailureRecord(reason):null;if(fail&&!commitQuestFailure(reason)){if(dead)showQuestFailureOutcome(reason,receipt,false);return false;}const result=questFailureReturnBase();if(villageOpen){questFailureDeathReceipt=null;if(receipt)showQuestFailureOutcome(reason,receipt);}return result;};
const questFailureMenuBase=worldMenu;worldMenu=(...args)=>{const result=questFailureMenuBase(...args);if(args[2]!=='questOutcome')$('card').removeAttribute('data-quest-outcome');return result;};
const questFailurePadBase=padMenu;padMenu=(g,l,r,dt)=>{if(menuSurface==='questOutcome'&&(padEdge(g,'back')||padEdge(g,'pause'))){if(!dead)showVillage();return;}return questFailurePadBase(g,l,r,dt);};
